/* saveTrprReg - Baek GyuHa */
SELECT CASE WHEN COUNT(RECIPI_MNG_NO) = 0 THEN 'SP' || TO_CHAR(SYSDATE,'YYYYMMDD') || LPAD(NVL(MAX(RECIPI_MNG_NO),0)+1,5,'0') ELSE 'SP' || TO_CHAR(SYSDATE,'YYYYMMDD') || LPAD((MAX(NVL(SUBSTR(RECIPI_MNG_NO,-5),0)) + 1),5,'0') END RECIPI_MNG_NO FROM AEB130 /* 자립지원수당기본 */ WHERE RECIPI_MNG_NO LIKE '%' || TO_CHAR(SYSDATE,'YYYYMMDD') || '%'
INSERT INTO AEB130 /* 자립지원수당기본 */ ( RECIPI_MNG_NO ,TRPR_INFO_NO ,INST_NO ,FRST_RGTR_ID ,FRST_REG_DT ,LAST_MDFR_ID ,LAST_MDFCN_DT ) VALUES ( #{RECIPI_MNG_NO} ,#{TRPR_INFO_NO} ,#{INST_NO} ,#{USER_ID2} ,SYSDATE ,#{USER_ID2} ,SYSDATE )

mapper.delete:

/* deleteTrprReg - Baek GyuHa */

DELETE FROM AEB130 /* 자립지원수당기본 */
WHERE RECIPI_MNG_NO = #{RECIPI_MNG_NO}

mapper.update:
/* deletePensnGiveDcsnReg - Baek GyuHa */
UPDATE AEB131 /* 자립지원수당상태 */
SET        
    DEL_YN = 'Y',
    LAST_MDFR_ID = #{USER_ID2},
    LAST_MDFCN_DT = SYSDATE
WHERE RECIPI_MNG_NO = #{RECIPI_MNG_NO}
AND PENSN_GIVE_STTS_SE_CD = #{PENSN_GIVE_STTS_SE_CD}
AND PENSN_GIVE_STTS_OCRN_YMD = #{PENSN_GIVE_STTS_OCRN_YMD}
